<?php
require 'config.php'; require_login();
$q=trim($_GET['q']??'');$dept=(int)($_GET['dept']??0);$status=$_GET['status']??'';$allowed=['Active','On Leave','Resigned'];
$where=[];$params=[];if($q!==''){$where[]='(e.emp_no LIKE ? OR e.first_name LIKE ? OR e.last_name LIKE ? OR e.email LIKE ?)';array_push($params,"%$q%","%$q%","%$q%","%$q%");}if($dept){$where[]='e.department_id=?';$params[]=$dept;}if(in_array($status,$allowed,true)){$where[]='e.status=?';$params[]=$status;}$w=$where?'WHERE '.implode(' AND ',$where):'';
$count=$pdo->prepare("SELECT COUNT(*) FROM employees e $w");$count->execute($params);$total=(int)$count->fetchColumn();$page=max(1,(int)($_GET['page']??1));$per=10;$pages=max(1,(int)ceil($total/$per));$page=min($page,$pages);$offset=($page-1)*$per;
$sql="SELECT e.*,d.department_name,p.position_title,(SELECT COUNT(*) FROM employee_projects ep WHERE ep.employee_id=e.employee_id) project_count FROM employees e JOIN departments d ON d.department_id=e.department_id JOIN positions p ON p.position_id=e.position_id $w ORDER BY e.last_name,e.first_name LIMIT $per OFFSET $offset";$st=$pdo->prepare($sql);$st->execute($params);$rows=$st->fetchAll();
$stats=$pdo->query("SELECT COUNT(*) total, COALESCE(SUM(status='Active'),0) active, COALESCE(SUM(status='On Leave'),0) onleave, COALESCE(SUM(status='Resigned'),0) resigned FROM employees")->fetch();$deptRows=$pdo->query('SELECT department_id,department_name FROM departments ORDER BY department_name')->fetchAll();
$deptStats=$pdo->query('SELECT d.department_name,COUNT(e.employee_id) headcount,COALESCE(ROUND(AVG(e.salary),2),0) avg_salary FROM departments d LEFT JOIN employees e ON e.department_id=d.department_id GROUP BY d.department_id,d.department_name ORDER BY headcount DESC')->fetchAll();
include 'includes/header.php'; ?>
<section class="hero"><div><p class="eyebrow">PEOPLE · PERFORMANCE · PROGRESS</p><h1>Employee Dashboard</h1><p class="muted">A clear overview of employee records and workforce distribution.</p></div><?php if(is_admin()):?><a class="btn gold" href="employee_form.php">+ Add Employee</a><?php endif;?></section>
<div class="stats"><article class="stat"><span>Total employees</span><strong><?=$stats['total']?></strong></article><article class="stat"><span>Active</span><strong><?=$stats['active']?></strong></article><article class="stat"><span>On leave</span><strong><?=$stats['onleave']?></strong></article><article class="stat"><span>Resigned</span><strong><?=$stats['resigned']?></strong></article></div>
<section class="panel"><div class="panel-head"><h2>Employee Directory</h2><div class="actions"><a class="btn outline" href="export.php?<?=e(http_build_query($_GET))?>">Export CSV</a><a class="btn outline" href="report.php?<?=e(http_build_query($_GET))?>" target="_blank">Print report</a></div></div>
<form class="filters" method="get"><input name="q" placeholder="Search name, employee ID, email" value="<?=e($q)?>"><select name="dept"><option value="0">All departments</option><?php foreach($deptRows as $d):?><option value="<?=$d['department_id']?>" <?=$dept===$d['department_id']?'selected':''?>><?=e($d['department_name'])?></option><?php endforeach;?></select><select name="status"><option value="">All statuses</option><?php foreach($allowed as $s):?><option <?=$status===$s?'selected':''?>><?=$s?></option><?php endforeach;?></select><button class="btn gold">Apply filters</button><a class="btn outline" href="index.php">Reset</a></form>
<div class="table-wrap"><table><thead><tr><th>Employee ID</th><th>Employee</th><th>Department</th><th>Position</th><th>Hire date</th><?php if(is_admin()):?><th>Monthly salary</th><?php endif;?><th>Projects</th><th>Status</th><?php if(is_admin()):?><th>Actions</th><?php endif;?></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="9" class="empty">No employee records found.</td></tr><?php endif;?><?php foreach($rows as $r):?><tr><td class="mono"><?=e($r['emp_no'])?></td><td><b><?=e($r['first_name'].' '.$r['last_name'])?></b><small><?=e($r['email'])?></small></td><td><?=e($r['department_name'])?></td><td><?=e($r['position_title'])?></td><td><?=e($r['hire_date'])?></td><?php if(is_admin()):?><td>₱<?=number_format($r['salary'],2)?></td><?php endif;?><td><?=$r['project_count']?></td><td><span class="badge <?=strtolower(str_replace(' ','',$r['status']))?>"><?=e($r['status'])?></span></td><?php if(is_admin()):?><td class="nowrap"><a href="employee_form.php?id=<?=$r['employee_id']?>">Edit</a><form class="inline" method="post" action="delete.php" onsubmit="return confirm('Delete this employee record?')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$r['employee_id']?>"><button class="text-danger">Delete</button></form></td><?php endif;?></tr><?php endforeach;?></tbody></table></div>
<div class="pager"><span><?=$total?> record(s) · Page <?=$page?> of <?=$pages?></span><div><?php for($i=1;$i<=$pages;$i++):$paramsPage=$_GET;$paramsPage['page']=$i;?><a class="<?=$i===$page?'current':''?>" href="?<?=e(http_build_query($paramsPage))?>"><?=$i?></a><?php endfor;?></div></div></section>
<section class="panel"><div class="panel-head"><h2>Department Overview</h2><p class="muted">Headcount and average monthly salary</p></div><div class="table-wrap"><table><thead><tr><th>Department</th><th>Employees</th><th>Average salary</th></tr></thead><tbody><?php foreach($deptStats as $ds):?><tr><td><?=e($ds['department_name'])?></td><td><?=$ds['headcount']?></td><td>₱<?=number_format($ds['avg_salary'],2)?></td></tr><?php endforeach;?></tbody></table></div></section>
<?php include 'includes/footer.php'; ?>
